public interface OrderRepository extends JpaRepository<Order, Long> {
    Optional<Order> findFirstByOrderByCreatedAtDesc();        // newest single order
    List<Order> findTop5ByStatusOrderByCreatedAtDesc(String status); // newest 5 in status
    List<Order> findTop3ByOrderByTotalDesc();                 // 3 highest totals
}

// usage
List<Order> latest = orderRepository.findTop5ByStatusOrderByCreatedAtDesc("OPEN");
