```java
public interface OrderRepository extends JpaRepository<Order, Long> {

    @Query("SELECT o FROM Order o WHERE o.status = :status AND o.total > :min")
    List<Order> expensive(@Param("status") String status, @Param("min") BigDecimal min);

    @Query("SELECT o FROM Order o JOIN FETCH o.customer WHERE o.customer.city = :city")
    List<Order> withCustomerByCity(@Param("city") String city); // avoids N+1

    @Query(value = "SELECT * FROM orders WHERE created_at > NOW() - INTERVAL '7 days'",
           nativeQuery = true)
    List<Order> recent(); // PostgreSQL-specific

    @Modifying @Transactional
    @Query("UPDATE Order o SET o.status = :s WHERE o.id = :id")
    int updateStatus(@Param("id") Long id, @Param("s") String s);
}
```

